"""Emit public catalogue metadata from the checked-in lesson source (no learner data)."""
import json,pathlib
root=pathlib.Path(__file__).resolve().parents[2]
packs=json.loads((root/'src/data/study-packs.json').read_text());files={f['id']:f for f in json.loads((root/'src/data/study-pack-files.json').read_text())}
rows=[{'id':p['id'],'title':p['title'],'subject':p['subject'],'grade':f"Grade {p['grade']}",'url':p['pdfUrl'],'bytes':files[p['id']]['bytes'],'sha256':files[p['id']]['sha256'],'topic':p['capsTopic'],'language':p['language'],'source':p['sourceUrl'],'edition':p['edition']} for p in packs]
sql='''-- Generated by scripts/content/publish_catalogue.py; original, free SmartBridge topic guides.
insert into public.resources(title,description,subject,grade,type,file_url,is_premium,is_approved,is_rejected,is_archived,file_name,file_size_bytes,file_type,file_extension,caps_alignment,language,version,tags,metadata)
select 'SmartBridge FET · '||x.title,'Focused topic guide: visual explanation, worked example, three practice questions and answer guide. Selected-topic supplement; subject-teacher and language-specialist review pending.',x.subject,x.grade,'Notes',x.url,false,true,false,false,split_part(x.url,'/',3),x.bytes,'application/pdf','pdf',x.topic,x.language,x.edition,array['SmartBridge FET','Topic guide','Free','Visual learning'],jsonb_build_object('smartbridge_pack_id',x.id,'caps_source',x.source,'sha256',x.sha256,'scope','selected topic','review_status','subject teacher review pending','reader_url','/study-packs/'||x.id)
from jsonb_to_recordset($catalogue$'''+json.dumps(rows,ensure_ascii=False)+'''$catalogue$::jsonb) as x(id text,title text,subject text,grade text,url text,bytes integer,sha256 text,topic text,language text,source text,edition text)
where not exists(select 1 from public.resources r where r.metadata->>'smartbridge_pack_id'=x.id);
'''
chunks=[]
for p in packs:
 prefix='SmartBridge FET first edition; subject-teacher review pending. CAPS focus: '+p['capsTopic']+'. '
 for page,number,text in [(1,1,' '.join(p['notes'])),(1,2,p['example']+' '+' '.join(p['steps'])),(2,1,' '.join(str(i+1)+'. '+q+' Answer: '+p['answers'][i] for i,q in enumerate(p['questions'])) )]:
  value=prefix+text
  assert 20<=len(value)<=2500
  chunks.append({'pack_id':p['id'],'page':page,'number':number,'content':value})
sql+='''\n-- Index the original guide text; preserve all pre-existing publisher passages.
insert into public.learning_knowledge_chunks(source_type,source_id,title,subject,grade,page_number,chunk_number,content)
select 'resources',r.id,r.title,r.subject,r.grade,c.page,c.number,c.content
from jsonb_to_recordset($chunks$'''+json.dumps(chunks,ensure_ascii=False)+'''$chunks$::jsonb) as c(pack_id text,page integer,number integer,content text)
join public.resources r on r.metadata->>'smartbridge_pack_id'=c.pack_id
where r.is_approved=true and r.is_premium=false and coalesce(r.is_archived,false)=false
on conflict(source_type,source_id,page_number,chunk_number) do update set content=excluded.content,indexed_at=now();
'''
(root/'db/publish-study-catalogue.sql').write_text(sql)
print('Prepared catalogue publication for',len(rows),'guides')
